drop function if exists public.admin_approve_payment_request(uuid,text,text); create function public.admin_approve_payment_request(_request_id uuid,_decision text,_notes text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare r public.payment_requests; caller uuid:=auth.uid(); begin if caller is null then raise exception 'Authentication required'; end if; if not public.user_has_permission(caller,'admin:approve_payments') then raise exception 'You do not have permission to approve payments'; end if; if lower(_decision) not in ('approved','rejected') then raise exception 'Invalid payment decision'; end if; select * into r from public.payment_requests where id=_request_id for update; if not found then raise exception 'Payment request not found'; end if; if r.status <> 'pending' then raise exception 'Payment request is already processed'; end if; if lower(_decision)='approved' then update public.payment_requests set status='approved',processed_by=caller,processed_at=now(),admin_notes=nullif(trim(coalesce(_notes,'')),'') ,updated_at=now() where id=r.id; update public.orders set payment_status='paid',updated_at=now() where payment_reference=r.reference and payment_status='awaiting_approval'; update public.estate_documentation_payments set status='paid',updated_at=now() where reference=r.reference and status='awaiting_approval'; update public.payments set status=case when balance<=0 then 'completed' else 'active' end,updated_at=now() where reference=r.reference and status='awaiting_approval'; else update public.payment_requests set status='rejected',processed_by=caller,processed_at=now(),admin_notes=nullif(trim(coalesce(_notes,'')),'') ,updated_at=now() where id=r.id; update public.orders set payment_status='rejected',updated_at=now() where payment_reference=r.reference and payment_status='awaiting_approval'; update public.estate_documentation_payments set status='rejected',updated_at=now() where reference=r.reference and status='awaiting_approval'; update public.payments set status='rejected',updated_at=now() where reference=r.reference and status='awaiting_approval'; end if; return jsonb_build_object('success',true,'request_id',r.id,'decision',lower(_decision)); end; $$; revoke all on function public.admin_approve_payment_request(uuid,text,text) from public; grant execute on function public.admin_approve_payment_request(uuid,text,text) to authenticated;
